public class Raid798Check{
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}
 static int soldiers(Battle b){int n=0;for(var u:b.units)if(u.hp>0&&u.npc==TribalRules.SPEAR)n++;return n;}
 public static void main(String[] args){var b=TribalCheck.battle(1,0);b.tribalFx=120;b.tribalState=TribalRules.OPENING;int chief=b.units[1].x;for(int i=0;i<36;i++)TribalRules.tickEffect(b);ok(b.units[1].x>chief,"Opening warrior retreat");int first=-1;for(int i=0;i<b.unitCount;i++)if(b.units[i].npc==TribalRules.SPEAR){first=i;break;}int x=b.units[first].x;for(int i=36;i<90;i++)TribalRules.tickEffect(b);ok(b.units[first].x<x,"Formation walks after retreat");TribalRules.wave(b);ok(soldiers(b)==6,"No overfill after initial six");TribalRules.wave(b);ok(soldiers(b)==6,"Six soldier cap");int goal=b.tribalGoal;b.units[1].hp=0;TribalRules.check(b);TribalRules.round(b);ok(b.units[1].hp>0&&b.tribalGoal==goal,"Warrior respawns without consuming troop goal");b.tribalFx=0;b.active=1;b.tribalClock=0;b.ballCount=0;for(int i=0;i<73;i++)TribalRules.tickAI(b);ok(b.ballCount==3,"Warrior walks then throws three spears");TribalCheck.testRules();System.out.println("PASS opening retreat/march, six troop cap, revival and three spears");}
}
